#!/usr/bin/env python3
"""Offline, defensive auditor for a synthetic QUIC v1 receiver model.

Reads one UTF-8 JSON document from stdin, writes one JSON document to stdout.

The model is a finite, local re-implementation of the packet/frame boundary
policies described in the task contract.  It never parses wire packets, never
performs TLS and never touches the network.
"""

import bisect
import json
import sys

# ---------------------------------------------------------------------------
# Limits and domains
# ---------------------------------------------------------------------------

MAXVAR = 4611686018427387903          # 2**62 - 1
MAX_FRAME_BYTES = 2048                # decoded bytes per data frame
MAX_TOTAL_FRAME_BYTES = 2 * 1024 * 1024
MAX_TRACES = 32
MAX_EVENTS = 20000
MAX_PACKETS = 20000
MAX_FRAMES = 60000
MAX_RANGES = 32
MAX_FRAMES_PER_PACKET = 64
MAX_PACKETS_PER_DATAGRAM = 16
MAX_T = 1000000000000
MAX_DATAGRAM_BYTES = 65535

HEX_DIGITS = frozenset("0123456789abcdef")
ID_CHARS = frozenset(
    "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789_-"
)
LEVELS = ("I", "H", "Z", "A")
KEY_ACTIONS = ("install", "discard")
OVERLAP_POLICIES = ("reject", "first")


class InvalidInput(Exception):
    """Raised when the request violates the input grammar."""


class ProtocolError(Exception):
    """Raised while applying frames; carries the offending frame index."""

    def __init__(self, code, frame=None):
        Exception.__init__(self, code)
        self.code = code
        self.frame = frame


class ConflictError(Exception):
    """Raised by the byte store when a rejected overlap is detected."""


# ---------------------------------------------------------------------------
# Input parsing
# ---------------------------------------------------------------------------


def _reject_constant(_name):
    raise InvalidInput("non-finite number")


def _object_pairs(pairs):
    obj = {}
    for key, value in pairs:
        if key in obj:
            raise InvalidInput("duplicate key")
        obj[key] = value
    return obj


def parse_document(raw):
    """Decode and parse the request, rejecting anything malformed."""
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError:
        raise InvalidInput("invalid utf-8")
    decoder = json.JSONDecoder(
        object_pairs_hook=_object_pairs, parse_constant=_reject_constant
    )
    stripped = text.lstrip()
    try:
        value, end = decoder.raw_decode(stripped)
    except InvalidInput:
        raise
    except (ValueError, RecursionError):
        raise InvalidInput("malformed json")
    if stripped[end:].strip():
        raise InvalidInput("trailing json")
    return value


# ---------------------------------------------------------------------------
# Input validation
# ---------------------------------------------------------------------------


def _exact_keys(obj, keys):
    if not isinstance(obj, dict):
        raise InvalidInput("expected object")
    if len(obj) != len(keys) or any(k not in obj for k in keys):
        raise InvalidInput("unexpected key set")


def _int(value, low, high):
    if type(value) is not int:
        raise InvalidInput("expected integer")
    if value < low or value > high:
        raise InvalidInput("integer out of domain")
    return value


def _bool(value):
    if type(value) is not bool:
        raise InvalidInput("expected boolean")
    return value


def _string(value):
    if not isinstance(value, str):
        raise InvalidInput("expected string")
    return value


def _hex_bytes(value):
    if not isinstance(value, str):
        raise InvalidInput("expected string")
    if len(value) % 2:
        raise InvalidInput("odd hex length")
    if len(value) > 2 * MAX_FRAME_BYTES:
        raise InvalidInput("hex payload too large")
    for ch in value:
        if ch not in HEX_DIGITS:
            raise InvalidInput("bad hex digit")
    return bytes.fromhex(value)


def _validate_ranges(value, strict):
    """Validate a RANGES value.

    ``strict`` is used for CONFIG.sent where ordering is part of the grammar.
    Frame ACK ranges share the endpoint/length domains but their ordering is a
    protocol matter, handled during replay.
    """
    if not isinstance(value, list):
        raise InvalidInput("expected array")
    if len(value) > MAX_RANGES:
        raise InvalidInput("too many ranges")
    out = []
    prev_high = None
    for item in value:
        if not isinstance(item, list) or len(item) != 2:
            raise InvalidInput("expected range pair")
        low = _int(item[0], 0, MAXVAR)
        high = _int(item[1], 0, MAXVAR)
        if strict:
            if low > high:
                raise InvalidInput("reversed range")
            if prev_high is not None and low <= prev_high + 1:
                raise InvalidInput("unsorted/adjacent ranges")
            prev_high = high
        out.append((low, high))
    return out


def _validate_config(config):
    _exact_keys(
        config,
        (
            "early",
            "overlap",
            "buffer_packets",
            "idle_ms",
            "max_streams_bidi",
            "max_streams_uni",
            "max_stream_data",
            "max_data",
            "crypto_limit",
            "sent",
        ),
    )
    early = _bool(config["early"])
    overlap = _string(config["overlap"])
    if overlap not in OVERLAP_POLICIES:
        raise InvalidInput("bad overlap policy")
    buffer_packets = _int(config["buffer_packets"], 0, 1024)
    idle_ms = _int(config["idle_ms"], 0, 1000000000)
    max_streams_bidi = _int(config["max_streams_bidi"], 0, 1024)
    max_streams_uni = _int(config["max_streams_uni"], 0, 1024)
    max_stream_data = _int(config["max_stream_data"], 0, 65536)
    max_data = _int(config["max_data"], 0, MAXVAR)
    crypto_limit = _int(config["crypto_limit"], 0, 65536)
    sent_raw = config["sent"]
    _exact_keys(sent_raw, ("I", "H", "A"))
    sent = {}
    for level in ("I", "H", "A"):
        sent[level] = _validate_ranges(sent_raw[level], True)
    return {
        "early": early,
        "overlap": overlap,
        "buffer_packets": buffer_packets,
        "idle_ms": idle_ms,
        "max_streams_bidi": max_streams_bidi,
        "max_streams_uni": max_streams_uni,
        "max_stream_data": max_stream_data,
        "max_data": max_data,
        "crypto_limit": crypto_limit,
        "sent": sent,
    }


def _validate_frame(frame, budget):
    if not isinstance(frame, dict):
        raise InvalidInput("expected frame object")
    ftype = frame.get("type")
    if not isinstance(ftype, str):
        raise InvalidInput("missing frame type")
    if ftype == "PADDING":
        _exact_keys(frame, ("type",))
        return ("PADDING",)
    if ftype == "PING":
        _exact_keys(frame, ("type",))
        return ("PING",)
    if ftype == "ACK":
        _exact_keys(frame, ("type", "ranges"))
        return ("ACK", _validate_ranges(frame["ranges"], False))
    if ftype == "CRYPTO":
        _exact_keys(frame, ("type", "offset", "data_hex"))
        offset = _int(frame["offset"], 0, MAXVAR)
        data = _hex_bytes(frame["data_hex"])
        budget["data"] += len(data)
        if budget["data"] > MAX_TOTAL_FRAME_BYTES:
            raise InvalidInput("too much frame data")
        return ("CRYPTO", offset, data)
    if ftype == "STREAM":
        _exact_keys(frame, ("type", "id", "offset", "data_hex", "fin"))
        sid = _int(frame["id"], 0, MAXVAR)
        offset = _int(frame["offset"], 0, MAXVAR)
        data = _hex_bytes(frame["data_hex"])
        fin = _bool(frame["fin"])
        budget["data"] += len(data)
        if budget["data"] > MAX_TOTAL_FRAME_BYTES:
            raise InvalidInput("too much frame data")
        return ("STREAM", sid, offset, data, fin)
    if ftype == "RESET_STREAM":
        _exact_keys(frame, ("type", "id", "final_size"))
        sid = _int(frame["id"], 0, MAXVAR)
        final_size = _int(frame["final_size"], 0, MAXVAR)
        return ("RESET_STREAM", sid, final_size)
    if ftype == "STOP_SENDING":
        _exact_keys(frame, ("type", "id"))
        sid = _int(frame["id"], 0, MAXVAR)
        return ("STOP_SENDING", sid)
    if ftype == "CLOSE":
        _exact_keys(frame, ("type", "app", "code"))
        app = _bool(frame["app"])
        code = _int(frame["code"], 0, MAXVAR)
        return ("CLOSE", app, code)
    if ftype == "HANDSHAKE_DONE":
        _exact_keys(frame, ("type",))
        return ("HANDSHAKE_DONE",)
    if ftype == "UNKNOWN":
        _exact_keys(frame, ("type",))
        return ("UNKNOWN",)
    raise InvalidInput("unknown frame type")


def _validate_packet(packet, budget):
    if not isinstance(packet, dict):
        raise InvalidInput("expected packet object")
    _exact_keys(packet, ("level", "pn", "auth", "frames"))
    level = _string(packet["level"])
    if level not in LEVELS:
        raise InvalidInput("bad packet level")
    pn = _int(packet["pn"], 0, MAXVAR)
    auth = _bool(packet["auth"])
    frames = packet["frames"]
    if not isinstance(frames, list):
        raise InvalidInput("expected frames array")
    if len(frames) > MAX_FRAMES_PER_PACKET:
        raise InvalidInput("too many frames in packet")
    budget["frames"] += len(frames)
    if budget["frames"] > MAX_FRAMES:
        raise InvalidInput("too many frames")
    norm_frames = []
    for frame in frames:
        norm_frames.append(_validate_frame(frame, budget))
    return {"level": level, "pn": pn, "auth": auth, "frames": norm_frames}


def _validate_event(event, budget):
    if not isinstance(event, dict):
        raise InvalidInput("expected event object")
    op = event.get("op")
    if op == "key":
        _exact_keys(event, ("t", "op", "level", "action"))
        t = _int(event["t"], 0, MAX_T)
        level = _string(event["level"])
        if level not in LEVELS:
            raise InvalidInput("bad key level")
        action = _string(event["action"])
        if action not in KEY_ACTIONS:
            raise InvalidInput("bad key action")
        return t, {"op": "key", "level": level, "action": action}
    if op == "tick":
        _exact_keys(event, ("t", "op"))
        t = _int(event["t"], 0, MAX_T)
        return t, {"op": "tick"}
    if op == "datagram":
        _exact_keys(event, ("t", "op", "bytes", "packets"))
        t = _int(event["t"], 0, MAX_T)
        size = _int(event["bytes"], 0, MAX_DATAGRAM_BYTES)
        packets = event["packets"]
        if not isinstance(packets, list):
            raise InvalidInput("expected packets array")
        if len(packets) < 1 or len(packets) > MAX_PACKETS_PER_DATAGRAM:
            raise InvalidInput("bad packet count")
        budget["packets"] += len(packets)
        if budget["packets"] > MAX_PACKETS:
            raise InvalidInput("too many packets")
        norm_packets = []
        for packet in packets:
            norm_packets.append(_validate_packet(packet, budget))
        return t, {"op": "datagram", "bytes": size, "packets": norm_packets}
    raise InvalidInput("bad event op")


def _validate_trace(trace, budget):
    if not isinstance(trace, dict):
        raise InvalidInput("expected trace object")
    _exact_keys(trace, ("id", "config", "events"))
    tid = _string(trace["id"])
    if not (1 <= len(tid) <= 32):
        raise InvalidInput("bad trace id length")
    for ch in tid:
        if ch not in ID_CHARS:
            raise InvalidInput("bad trace id character")
    config = _validate_config(trace["config"])
    events = trace["events"]
    if not isinstance(events, list):
        raise InvalidInput("expected events array")
    budget["events"] += len(events)
    if budget["events"] > MAX_EVENTS:
        raise InvalidInput("too many events")
    norm_events = []
    previous_t = -1
    for event in events:
        t, norm = _validate_event(event, budget)
        if t < previous_t:
            raise InvalidInput("event time went backwards")
        previous_t = t
        norm_events.append(norm)
    return tid, config, norm_events


def validate_request(document):
    if not isinstance(document, dict):
        raise InvalidInput("expected object")
    _exact_keys(document, ("version", "traces"))
    if type(document["version"]) is not int or document["version"] != 1:
        raise InvalidInput("bad version")
    traces = document["traces"]
    if not isinstance(traces, list):
        raise InvalidInput("expected traces array")
    if len(traces) > MAX_TRACES:
        raise InvalidInput("too many traces")
    budget = {"events": 0, "packets": 0, "frames": 0, "data": 0}
    out = []
    seen = set()
    for trace in traces:
        tid, config, events = _validate_trace(trace, budget)
        if tid in seen:
            raise InvalidInput("duplicate trace id")
        seen.add(tid)
        out.append((tid, config, events))
    return out


# ---------------------------------------------------------------------------
# Sparse byte store
# ---------------------------------------------------------------------------


class ByteStore:
    """Sparse byte storage with overlap policy, contiguity and rollback.

    Bytes are kept as a sorted list of disjoint, non-adjacent chunks so that
    very large sparse offsets stay cheap.  Every mutation returns an undo
    callable so that a failed packet can be rolled back atomically.
    """

    __slots__ = ("starts", "chunks", "contig", "delivered")

    def __init__(self):
        self.starts = []
        self.chunks = {}
        self.contig = 0
        self.delivered = bytearray()

    # -- reading -----------------------------------------------------------
    def read(self, offset, length):
        """Return `length` bytes at `offset`, or None when not fully stored."""
        if length <= 0:
            return b""
        starts = self.starts
        chunks = self.chunks
        out = bytearray()
        pos = offset
        end = offset + length
        i = bisect.bisect_right(starts, offset) - 1
        if i < 0:
            i = 0
        while pos < end and i < len(starts):
            start = starts[i]
            chunk = chunks[start]
            stop = start + len(chunk)
            if stop <= pos:
                i += 1
                continue
            lo = pos if pos > start else start
            hi = stop if stop < end else end
            out += chunk[lo - start : hi - start]
            pos = hi
            i += 1
        if len(out) != length:
            return None
        return bytes(out)

    # -- writing -----------------------------------------------------------
    def insert(self, offset, data, policy):
        """Store `data` at `offset`; raise ConflictError on a rejected clash."""
        size = len(data)
        if size == 0:
            return _noop
        end = offset + size
        starts = self.starts
        chunks = self.chunks

        index = bisect.bisect_right(starts, offset) - 1
        if index < 0:
            index = 0
        overlapping = []
        while index < len(starts) and starts[index] < end:
            start = starts[index]
            chunk = chunks[start]
            if start + len(chunk) > offset:
                overlapping.append(index)
            index += 1

        merged = bytearray(data)
        removed = []
        for index in overlapping:
            start = starts[index]
            chunk = chunks[start]
            removed.append((start, chunk))
            lo = start if start > offset else offset
            hi = start + len(chunk)
            if hi > end:
                hi = end
            if hi > lo:
                old_seg = chunk[lo - start : hi - start]
                new_seg = merged[lo - offset : hi - offset]
                if old_seg != new_seg:
                    if policy == "reject":
                        raise ConflictError()
                    merged[lo - offset : hi - offset] = old_seg

        new_items = []
        for start, chunk in removed:
            if start < offset:
                new_items.append((start, chunk[: offset - start]))
            if start + len(chunk) > end:
                new_items.append((end, chunk[end - start :]))
        new_items.append((offset, bytes(merged)))

        if overlapping:
            first = overlapping[0]
            last = overlapping[-1] + 1
            for start, _chunk in removed:
                del chunks[start]
            del starts[first:last]
            position = first
        else:
            position = bisect.bisect_left(starts, offset)

        added = []
        for start, chunk in new_items:
            chunks[start] = chunk
            added.append(start)
        starts[position:position] = sorted(added)

        old_contig = self.contig
        old_delivered = len(self.delivered)
        self._extend_contiguous()

        def undo():
            for start in added:
                chunks.pop(start, None)
                idx = bisect.bisect_left(starts, start)
                while idx < len(starts) and starts[idx] < start:
                    idx += 1
                if idx < len(starts) and starts[idx] == start:
                    del starts[idx]
            for start, chunk in removed:
                chunks[start] = chunk
                bisect.insort(starts, start)
            self.contig = old_contig
            del self.delivered[old_delivered:]

        return undo

    def _extend_contiguous(self):
        starts = self.starts
        chunks = self.chunks
        contig = self.contig
        index = bisect.bisect_right(starts, contig) - 1
        if index < 0:
            index = 0
        while index < len(starts):
            start = starts[index]
            stop = start + len(chunks[start])
            if stop <= contig:
                index += 1
                continue
            if start > contig:
                break
            contig = stop
            index += 1
        if contig > self.contig:
            fresh = self.read(self.contig, contig - self.contig)
            if fresh:
                self.delivered += fresh
            self.contig = contig


def _noop():
    return None


class StreamState:
    __slots__ = ("sid", "highest", "final_size", "reset", "stopped", "store")

    def __init__(self, sid):
        self.sid = sid
        self.highest = 0
        self.final_size = None
        self.reset = False
        self.stopped = False
        self.store = ByteStore()


# ---------------------------------------------------------------------------
# Replay
# ---------------------------------------------------------------------------


def _level_permits(level, frame):
    ftype = frame[0]
    if ftype in ("PADDING", "PING"):
        return True
    if ftype in ("ACK", "CRYPTO"):
        return level in ("I", "H", "A")
    if ftype in ("STREAM", "RESET_STREAM", "STOP_SENDING"):
        return level in ("Z", "A")
    if ftype == "CLOSE":
        if frame[1]:
            return level in ("Z", "A")
        return True
    return False


def _ranges_contain(ranges, starts, low, high):
    """True when [low, high] is fully covered by the sorted `ranges`."""
    index = bisect.bisect_right(starts, low) - 1
    if index < 0:
        return False
    pos = low
    total = len(ranges)
    while index < total:
        start, stop = ranges[index]
        if start > pos:
            return False
        if stop >= high:
            return True
        pos = stop + 1
        index += 1
    return False


class Replay:
    def __init__(self, tid, config, events):
        self.tid = tid
        self.early = config["early"]
        self.policy = config["overlap"]
        self.buffer_packets = config["buffer_packets"]
        self.idle_ms = config["idle_ms"]
        self.max_bidi = config["max_streams_bidi"]
        self.max_uni = config["max_streams_uni"]
        self.max_stream_data = config["max_stream_data"]
        self.max_data = config["max_data"]
        self.crypto_limit = config["crypto_limit"]
        self.sent = config["sent"]
        self.sent_starts = {
            level: [r[0] for r in config["sent"][level]] for level in ("I", "H", "A")
        }
        self.events = events
        self.keys = {
            "I": "live",
            "H": "absent",
            "Z": "live" if self.early else "absent",
            "A": "absent",
        }
        self.queue = []
        self.streams = {}
        self.crypto = {"I": ByteStore(), "H": ByteStore(), "A": ByteStore()}
        self.crypto_highest = {"I": 0, "H": 0, "A": 0}
        self.received_total = 0
        self.pn_sets = {"I": set(), "H": set(), "A": set()}
        self.state = "open"
        self.code = None
        self.at_ms = None
        self.source = None
        self.peer_code = None
        self.last_activity = 0
        self.results = {}

    # -- bookkeeping -------------------------------------------------------
    def record(self, event, packet, status, reason, at_ms, frame):
        self.results[(event, packet)] = {
            "event": event,
            "packet": packet,
            "status": status,
            "reason": reason,
            "at_ms": at_ms,
            "frame": frame,
        }

    def terminate(self, state, code, at_ms, source, peer_code):
        self.state = state
        self.code = code
        self.at_ms = at_ms
        self.source = source
        self.peer_code = peer_code
        pending = self.queue
        self.queue = []
        for item in pending:
            self.record(
                item["event"], item["packet"], "dropped", "CONNECTION_CLOSED", at_ms, None
            )

    # -- main loop ---------------------------------------------------------
    def run(self):
        for index, event in enumerate(self.events):
            self.handle_event(index, event)
        for item in self.queue:
            self.record(
                item["event"], item["packet"], "buffered", "NO_KEYS", item["t"], None
            )
        self.queue = []

    def handle_event(self, index, event):
        now = event["t"]
        if self.state == "open" and self.idle_ms > 0:
            deadline = self.last_activity + self.idle_ms
            if now >= deadline:
                self.terminate(
                    "idle",
                    "IDLE_TIMEOUT",
                    deadline,
                    {"event": index, "packet": None, "frame": None},
                    None,
                )
        if self.state != "open":
            if event["op"] == "datagram":
                for packet_index in range(len(event["packets"])):
                    self.record(
                        index,
                        packet_index,
                        "dropped",
                        "CONNECTION_CLOSED",
                        now,
                        None,
                    )
            return
        op = event["op"]
        if op == "key":
            self.handle_key(index, event, now)
        elif op == "datagram":
            self.handle_datagram(index, event, now)
        # "tick" only advances logical time; nothing else to do.

    def handle_key(self, index, event, now):
        level = event["level"]
        action = event["action"]
        if action == "install":
            if self.keys[level] != "absent":
                return
            self.keys[level] = "live"
            pending = [item for item in self.queue if item["level"] == level]
            if pending:
                self.queue = [item for item in self.queue if item["level"] != level]
                for item in pending:
                    if self.state != "open":
                        self.record(
                            item["event"],
                            item["packet"],
                            "dropped",
                            "CONNECTION_CLOSED",
                            now,
                            None,
                        )
                        continue
                    self.process_packet(
                        item["event"],
                        item["packet"],
                        item["packet_data"],
                        now,
                        0,
                        True,
                    )
            return
        self.keys[level] = "discarded"
        pending = [item for item in self.queue if item["level"] == level]
        if pending:
            self.queue = [item for item in self.queue if item["level"] != level]
            for item in pending:
                self.record(
                    item["event"], item["packet"], "dropped", "KEYS_DISCARDED", now, None
                )

    def handle_datagram(self, index, event, now):
        packets = event["packets"]
        size = event["bytes"]
        total = len(packets)
        layout = False
        for position, packet in enumerate(packets):
            if packet["level"] == "A" and position != total - 1:
                layout = True
                break
        if layout:
            for position in range(total):
                self.record(index, position, "dropped", "LAYOUT", now, None)
            return
        for position, packet in enumerate(packets):
            if self.state != "open":
                self.record(
                    index, position, "dropped", "CONNECTION_CLOSED", now, None
                )
                continue
            self.process_packet(index, position, packet, now, size, False)

    # -- packet handling ---------------------------------------------------
    def process_packet(self, event, packet_index, packet, now, size, from_queue):
        level = packet["level"]
        if not from_queue and level == "I" and size < 1200:
            self.record(event, packet_index, "dropped", "INITIAL_TOO_SMALL", now, None)
            return
        if level == "Z" and not self.early:
            self.record(event, packet_index, "dropped", "EARLY_REJECTED", now, None)
            return
        key_state = self.keys[level]
        if key_state == "discarded":
            self.record(event, packet_index, "dropped", "KEYS_DISCARDED", now, None)
            return
        if key_state == "absent":
            if len(self.queue) < self.buffer_packets:
                self.queue.append(
                    {
                        "event": event,
                        "packet": packet_index,
                        "level": level,
                        "t": now,
                        "packet_data": packet,
                    }
                )
            else:
                self.record(event, packet_index, "dropped", "BUFFER_FULL", now, None)
            return
        if not packet["auth"]:
            self.record(event, packet_index, "dropped", "AUTH", now, None)
            return
        space = "A" if level in ("Z", "A") else level
        if packet["pn"] in self.pn_sets[space]:
            self.record(event, packet_index, "duplicate", "DUPLICATE", now, None)
            return
        self.apply_frames(event, packet_index, level, packet, now)

    def apply_frames(self, event, packet_index, level, packet, now):
        frames = packet["frames"]
        if not frames:
            self.fail(event, packet_index, None, "FRAME_ENCODING_ERROR", now)
            return
        for position, frame in enumerate(frames):
            if frame[0] == "UNKNOWN":
                self.fail(event, packet_index, position, "FRAME_ENCODING_ERROR", now)
                return
            if not _level_permits(level, frame):
                self.fail(event, packet_index, position, "PROTOCOL_VIOLATION", now)
                return
        undo = []
        for position, frame in enumerate(frames):
            if frame[0] == "CLOSE":
                self.commit(packet, now)
                code = (
                    "PEER_APPLICATION_CLOSE" if frame[1] else "PEER_TRANSPORT_CLOSE"
                )
                self.terminate(
                    "closed",
                    code,
                    now,
                    {"event": event, "packet": packet_index, "frame": position},
                    frame[2],
                )
                self.record(event, packet_index, "accepted", "OK", now, None)
                return
            try:
                self.apply_frame(level, frame, undo)
            except ProtocolError as error:
                for action in reversed(undo):
                    action()
                self.fail(event, packet_index, error.frame, error.code, now)
                return
        self.commit(packet, now)
        self.record(event, packet_index, "accepted", "OK", now, None)

    def commit(self, packet, now):
        level = packet["level"]
        space = "A" if level in ("Z", "A") else level
        self.pn_sets[space].add(packet["pn"])
        self.last_activity = now

    def fail(self, event, packet_index, frame, code, now):
        self.terminate(
            "closed",
            code,
            now,
            {"event": event, "packet": packet_index, "frame": frame},
            None,
        )
        self.record(event, packet_index, "error", code, now, frame)

    # -- frame semantics ---------------------------------------------------
    def apply_frame(self, level, frame, undo):
        ftype = frame[0]
        if ftype in ("PADDING", "PING"):
            return
        if ftype == "ACK":
            self.apply_ack(level, frame)
            return
        if ftype == "CRYPTO":
            self.apply_crypto(level, frame, undo)
            return
        if ftype == "STREAM":
            self.apply_stream(frame, undo)
            return
        if ftype == "RESET_STREAM":
            self.apply_reset(frame, undo)
            return
        if ftype == "STOP_SENDING":
            self.apply_stop(frame, undo)
            return

    def apply_ack(self, level, frame):
        ranges = frame[1]
        if not ranges:
            raise ProtocolError("FRAME_ENCODING_ERROR")
        previous_high = None
        for low, high in ranges:
            if low > high:
                raise ProtocolError("FRAME_ENCODING_ERROR")
            if previous_high is not None and low <= previous_high + 1:
                raise ProtocolError("FRAME_ENCODING_ERROR")
            previous_high = high
        sent = self.sent[level]
        starts = self.sent_starts[level]
        for low, high in ranges:
            if not _ranges_contain(ranges=sent, starts=starts, low=low, high=high):
                raise ProtocolError("PROTOCOL_VIOLATION")

    def apply_crypto(self, level, frame, undo):
        offset = frame[1]
        data = frame[2]
        end = offset + len(data)
        if end > MAXVAR:
            raise ProtocolError("FRAME_ENCODING_ERROR")
        if end > self.crypto_limit:
            raise ProtocolError("CRYPTO_BUFFER_EXCEEDED")
        store = self.crypto[level]
        try:
            undo.append(store.insert(offset, data, self.policy))
        except ConflictError:
            raise ProtocolError("PROTOCOL_VIOLATION")
        old_highest = self.crypto_highest[level]
        if end > old_highest:
            self.crypto_highest[level] = end
            undo.append(
                lambda lvl=level, value=old_highest: self.crypto_highest.__setitem__(
                    lvl, value
                )
            )

    def _stream_entry(self, sid, undo):
        stream = self.streams.get(sid)
        if stream is None:
            stream = StreamState(sid)
            self.streams[sid] = stream
            undo.append(lambda s=sid: self.streams.pop(s, None))
        return stream

    def _check_direction(self, sid):
        mode = sid % 4
        if mode not in (0, 2):
            raise ProtocolError("STREAM_STATE_ERROR")
        limit = self.max_bidi if mode == 0 else self.max_uni
        if sid // 4 + 1 > limit:
            raise ProtocolError("STREAM_LIMIT_ERROR")

    def apply_stream(self, frame, undo):
        sid = frame[1]
        offset = frame[2]
        data = frame[3]
        fin = frame[4]
        self._check_direction(sid)
        stream = self._stream_entry(sid, undo)
        end = offset + len(data)
        if end > MAXVAR:
            raise ProtocolError("FRAME_ENCODING_ERROR")
        if stream.final_size is not None and (
            end > stream.final_size or (fin and end != stream.final_size)
        ):
            raise ProtocolError("FINAL_SIZE_ERROR")
        if fin and end < stream.highest:
            raise ProtocolError("FINAL_SIZE_ERROR")
        if end > self.max_stream_data:
            raise ProtocolError("FLOW_CONTROL_ERROR")
        new_highest = stream.highest if stream.highest > end else end
        delta = new_highest - stream.highest
        if self.received_total + delta > self.max_data:
            raise ProtocolError("FLOW_CONTROL_ERROR")
        if not stream.reset:
            try:
                undo.append(stream.store.insert(offset, data, self.policy))
            except ConflictError:
                raise ProtocolError("PROTOCOL_VIOLATION")
        if delta:
            old_highest = stream.highest
            stream.highest = new_highest
            undo.append(lambda st=stream, value=old_highest: setattr(st, "highest", value))
            old_total = self.received_total
            self.received_total += delta
            undo.append(lambda value=old_total: setattr(self, "received_total", value))
        if fin and stream.final_size is None:
            old_final = stream.final_size
            stream.final_size = end
            undo.append(
                lambda st=stream, value=old_final: setattr(st, "final_size", value)
            )

    def apply_reset(self, frame, undo):
        sid = frame[1]
        final_size = frame[2]
        self._check_direction(sid)
        stream = self._stream_entry(sid, undo)
        if stream.final_size is not None and stream.final_size != final_size:
            raise ProtocolError("FINAL_SIZE_ERROR")
        if final_size < stream.highest:
            raise ProtocolError("FINAL_SIZE_ERROR")
        if final_size > self.max_stream_data:
            raise ProtocolError("FLOW_CONTROL_ERROR")
        new_highest = stream.highest if stream.highest > final_size else final_size
        delta = new_highest - stream.highest
        if self.received_total + delta > self.max_data:
            raise ProtocolError("FLOW_CONTROL_ERROR")
        if delta:
            old_highest = stream.highest
            stream.highest = new_highest
            undo.append(lambda st=stream, value=old_highest: setattr(st, "highest", value))
            old_total = self.received_total
            self.received_total += delta
            undo.append(lambda value=old_total: setattr(self, "received_total", value))
        old_final = stream.final_size
        stream.final_size = final_size
        undo.append(lambda st=stream, value=old_final: setattr(st, "final_size", value))
        old_reset = stream.reset
        stream.reset = True
        undo.append(lambda st=stream, value=old_reset: setattr(st, "reset", value))

    def apply_stop(self, frame, undo):
        sid = frame[1]
        if sid % 4 != 0:
            raise ProtocolError("STREAM_STATE_ERROR")
        if sid // 4 + 1 > self.max_bidi:
            raise ProtocolError("STREAM_LIMIT_ERROR")
        stream = self._stream_entry(sid, undo)
        if not stream.stopped:
            stream.stopped = True
            undo.append(lambda st=stream: setattr(st, "stopped", False))

    # -- output ------------------------------------------------------------
    def result(self):
        packets = [self.results[key] for key in sorted(self.results)]
        streams = []
        for sid in sorted(self.streams):
            stream = self.streams[sid]
            streams.append(
                {
                    "id": sid,
                    "highest": stream.highest,
                    "final_size": stream.final_size,
                    "reset": stream.reset,
                    "stopped": stream.stopped,
                    "delivered_hex": stream.store.delivered.hex(),
                }
            )
        crypto = []
        for level in ("I", "H", "A"):
            crypto.append(
                {
                    "level": level,
                    "highest": self.crypto_highest[level],
                    "contiguous_hex": self.crypto[level].delivered.hex(),
                }
            )
        connection = {
            "state": self.state,
            "code": self.code,
            "at_ms": self.at_ms,
            "source": self.source,
            "peer_code": self.peer_code,
            "last_activity_ms": self.last_activity,
        }
        return {
            "id": self.tid,
            "packets": packets,
            "connection": connection,
            "keys": dict(self.keys),
            "received_total": self.received_total,
            "streams": streams,
            "crypto": crypto,
        }


# ---------------------------------------------------------------------------
# Entry point
# ---------------------------------------------------------------------------


def emit(document):
    sys.stdout.write(json.dumps(document, separators=(",", ":")))
    sys.stdout.write("\n")
    sys.stdout.flush()


def main():
    raw = sys.stdin.buffer.read()
    try:
        document = parse_document(raw)
        traces = validate_request(document)
    except InvalidInput:
        emit({"error": "INVALID_INPUT"})
        return 0
    except RecursionError:
        emit({"error": "INVALID_INPUT"})
        return 0
    try:
        results = []
        for tid, config, events in traces:
            replay = Replay(tid, config, events)
            replay.run()
            results.append(replay.result())
    except Exception:
        emit({"error": "INVALID_INPUT"})
        return 0
    emit({"version": 1, "results": results})
    return 0


if __name__ == "__main__":
    sys.exit(main())
